import {vocabularyCatalog,esc} from './vocabulary_card.mjs';
export const levels=[['','全部程度'],['elem_1000','國小'],['jhs_2000','國中'],['shs_3000','高中'],['toeic','TOEIC'],['toefl','TOEFL'],['sat','SAT'],['gre','GRE'],['gmat','GMAT']];
let tier='',query='',items=null,limit=20,loadError=false;
export function renderLearningHub(){return `<article class="learning-hub"><p class="hub-eyebrow">ENGLISH QUEST · 每天一點，記得更久</p><h1>今天，想怎麼學？</h1><p class="hub-lead">選一組單字，或用一小關暖身。</p><div class="hub-primary"><a class="hub-tile words" href="#words"><span aria-hidden="true">Aa</span><strong>學單字</strong><small>選程度、找單字、聽讀翻卡</small><b>開始學習 →</b></a><a class="hub-tile games" href="quest/"><span aria-hidden="true">✦</span><strong>玩遊戲</strong><small>程度闖關、互動故事、錯題複習</small><b>進入冒險 →</b></a></div>${renderWordPicker()}<section class="hub-paths" aria-label="其他學習方式"><a href="mnemonics/"><span>💡</span><strong>聯想記憶</strong><small>1,000 字 · 口訣與翻面 MP3</small></a><a href="roots/"><span>🌱</span><strong>字根字族</strong><small>500 組 · 從零件理解單字</small></a><a href="#listening"><span>🎧</span><strong>會話聽讀</strong><small>情境、跟讀與表達</small></a><a href="EN/#vocab"><span>🌎</span><strong>全英文學習</strong><small>單字、英文解釋與例句</small></a></section><details class="hub-library"><summary>完整教材與其他工具</summary><div class="hub-library-links">${[['#knowledge','知識點與圖解'],['#curriculum108','學年課程'],['#grammar','文法教室'],['#diagnostic','程度檢核'],['#flashcards','閃卡練習'],['#wordpractice','拼字與複習'],['#progress','學習紀錄']].map(([url,label])=>`<a href="${url}">${label} →</a>`).join('')}</div></details></article>`;}
export function renderWordPicker(){return `<section class="hub-picker" id="word-picker"><div class="hub-section-title"><h2>選你要學的單字</h2><a href="#wordaudio">繼續上次聽讀 →</a></div><label for="hub-search">搜尋英文或中文</label><input id="hub-search" type="search" value="${esc(query)}" placeholder="例如 ambulance、救護車" autocomplete="off"><div class="hub-levels" role="group" aria-label="選擇程度">${levels.map(([id,name])=>`<button data-hub-tier="${id}" aria-pressed="${tier===id}">${name}</button>`).join('')}</div><div id="hub-results" aria-live="polite">正在準備單字…</div></section>`;}
function results(){const box=document.querySelector('#hub-results');if(!box)return;
 if(!items){box.innerHTML=loadError?'<p>單字目錄暫時無法載入。</p><button data-hub-retry>重新載入</button><a href="#wordaudio">前往 MP3 選組</a>':'<p>正在準備單字…</p>';return;}
 const q=query.trim().toLowerCase(),matches=items.filter(c=>(!tier||c.tier===tier)&&(!q||c.word.toLowerCase().includes(q)||c.zh.includes(q)));
 box.innerHTML=`<p class="hub-count">${matches.length.toLocaleString()} 張字卡${matches.length>limit?` · 先顯示 ${limit} 張`:''}</p><div class="hub-word-results">${matches.slice(0,limit).map(c=>`<a href="#wordaudio/${c.group}/${c.id}" class="hub-word"><span aria-hidden="true">${esc(c.icon)}</span><div><strong lang="en">${esc(c.word)}</strong><small>${esc(c.zh)}</small></div><b aria-hidden="true">▶</b></a>`).join('')}</div>${matches.length>limit?'<button class="hub-more" data-hub-more>再看 20 張</button>':''}${!matches.length?'<p>沒有符合的單字。試試較短的字詞或切換全部程度。</p>':''}`;
}
function load(){loadError=false;results();vocabularyCatalog().then(data=>{items=data;results();}).catch(()=>{loadError=true;results();});}
export function bindLearningHub(root){const picker=root.querySelector('#word-picker');if(!picker)return;
 root.querySelector('#hub-search').addEventListener('input',e=>{query=e.target.value;limit=20;results();});
 picker.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if('hubTier'in b.dataset){tier=b.dataset.hubTier;limit=20;picker.querySelectorAll('[data-hub-tier]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.hubTier===tier)));results();}if('hubMore'in b.dataset){limit+=20;results();}if('hubRetry'in b.dataset)load();});
 if(items)results();else load();
}
